279	    protected String getDataOf(VcsFileRevision object) {
280	      final String originalMessage = object.getCommitMessage();
281	      if (originalMessage != null) {
282	        String commitMessage = originalMessage.trim();
283	        int index13 = commitMessage.indexOf('\r');
284	        int index10 = commitMessage.indexOf('\n');
285	
286	        if (index10 < 0 && index13 < 0) {
287	          return commitMessage;
288	        }
289	        else {
290	          return commitMessage.substring(0, getSuitableIndex(index10, index13)) + "...";
291	        }
292	      }
293	      else {
294	        return "";
295	      }
296	    }
297	
298	    private static int getSuitableIndex(int index10, int index13) {
299	      if (index10 < 0) {
300	        return index13;
301	      }
302	      else if (index13 < 0) {
303	        return index10;
304	      }
305	      else {
306	        return Math.min(index10, index13);
307	      }
308	    }
