610	  private void showDifferences(Project project, VcsFileRevision revision1, VcsFileRevision revision2) {
611	    VcsFileRevision left = revision1;
612	    VcsFileRevision right = revision2;
613	    if (VcsHistoryUtil.compare(revision1, revision2) > 0) {
614	      left = revision2;
615	      right = revision1;
616	    }
617	
618	    try {
619	      final String leftTitle = left.getRevisionNumber().asString() + (left instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
620	      final String rightTitle = right.getRevisionNumber().asString() + (right instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
621	      VcsHistoryUtil.showDiff(project, myFilePath, left, right, leftTitle, rightTitle);
622	    } catch (final VcsException e) {
623	      WaitForProgressToShow.runOrInvokeLaterAboveProgress(new Runnable() {
624	        public void run() {
625	          Messages.showErrorDialog(VcsBundle.message("message.text.cannot.show.differences", e.getLocalizedMessage()),
626	                                   VcsBundle.message("message.title.show.differences"));
627	        }
628	      }, null, project);
629	    } catch (IOException e) {
630	      LOG.error(e);
631	    } catch (ProcessCanceledException ex) {
632	      LOG.info(ex);
633	    }
634	  }
