935	        if (ReadonlyStatusHandler.getInstance(myVcs.getProject()).ensureFilesWritable(file).hasReadonlyFiles()) {
936	          return;
937	        }
938	      }
939	
940	      LocalHistoryAction action = file != null ? startLocalHistoryAction(revision) : LocalHistoryAction.NULL;
941	
942	      final byte[] revisionContent;
943	      try {
944	        revisionContent = VcsHistoryUtil.loadRevisionContent(revision);
945	      }
946	      catch (IOException e) {
947	        LOG.info(e);
948	        Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
949	                                   VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
950	        return;
951	      }
952	      catch (VcsException e) {
953	        Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
954	                                   VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
955	        return;
956	      }
957	      catch (ProcessCanceledException ex) {
958	        return;
959	      }
960	      final byte[] finalRevisionContent = revisionContent;
961	      try {
962	        ApplicationManager.getApplication().runWriteAction(new Runnable() {
963	          public void run() {
964	            CommandProcessor.getInstance().executeCommand(myVcs.getProject(), new Runnable() {
965	                public void run() {
966	                  try {
967	                    write(finalRevisionContent);
968	                  }
969	                  catch (IOException e) {
970	                    Messages.showMessageDialog(VcsBundle.message("message.text.cannot.save.content", e.getLocalizedMessage()),
971	                                               VcsBundle.message("message.title.get.revision.content"), Messages.getErrorIcon());
972	                  }
973	                }
974	              }, createGetActionTitle(revision), null);
975	          }
976	        });
977	        if (file != null) {
978	          VcsDirtyScopeManager.getInstance(myVcs.getProject()).fileDirty(file);
979	        }
980	      }
981	      finally {
982	        action.finish();
983	      }
984	    }
